"""Bounded same-model final self-check for supplied-context short-answer QA.

This middleware never sees ground truth and never calls a side model. It runs
after deterministic formatting gates. For a draft answer whose generic shape is
a known exact-match risk, it asks the same primary model to re-read the
supplied context and re-emit only the corrected short answer.

Bounds:
  * at most one continue per run (tracked in ``ctx.state``); the runtime also
    caps the total number of final continues;
  * only fires for supplied-context tasks whose prompt says
    "Return only the short answer";
  * closed-form answers (yes/no, bare numbers, "not stated") are accepted
    unchanged;
  * every trigger is a generic question/draft shape check, never a stored task
    id or expected answer. Names shown in feedback are copied from the supplied
    context at run time.
"""

from __future__ import annotations

import re

_CONTEXT_MARKER = re.compile(r"\r?\n\r?\n?Context:\r?\n")
_QUESTION_MARKER = re.compile(r"\r?\n\r?\n?Question:\r?\n")

_CLOSED_FORM = re.compile(
    r"^(?:yes|no|\d[\d,]*(?:\.\d+)?|not stated|not mentioned|unknown|not in the context)$",
    re.IGNORECASE,
)

_SINGULAR_WHO = re.compile(r"^who\b", re.IGNORECASE)
_PLURAL_WHO = re.compile(r"^who\s+(?:are|were)\b", re.IGNORECASE)
_CATEGORY_QUESTION = re.compile(
    r"\bwhat\s+(?:kind|type|style|genre|sort|category|class)\s+of\s+",
    re.IGNORECASE,
)
_AWARD_QUESTION = re.compile(r"\b(?:what|which)\s+award\b", re.IGNORECASE)
_ALTERNATIVE_QUESTION = re.compile(r"\s+or\s+", re.IGNORECASE)
_OTHER_QUESTION = re.compile(r"\b(?:what|which)\s+other\b", re.IGNORECASE)
_LABEL_QUESTION = re.compile(
    r"\bwhat\s+(?:sport|role|activity|field|industry|position|title)\b",
    re.IGNORECASE,
)
_PERSON_QUESTION = re.compile(
    r"\b(?:who|whom|comedian|actor|actress|author|writer|man|woman|artist|"
    r"activist|politician|player|singer|musician|collaborator|person)\b",
    re.IGNORECASE,
)

_PROPER_NOUN_PHRASE = re.compile(r"[A-Z][A-Za-z0-9'.\-]*(?:\s+[A-Z][A-Za-z0-9'.\-]*)*")
_COMMA_EXTENSION = re.compile(
    r"\s*,\s+([A-Z][A-Za-z0-9'.\-]*(?:\s+[A-Z][A-Za-z0-9'.\-]*)*)"
)


def _is_supplied_context_qa(question: str) -> bool:
    if not question:
        return False
    if "short answer" not in question.lower():
        return False
    if not _CONTEXT_MARKER.search(question):
        return False
    return bool(_QUESTION_MARKER.search(question))


def _split_question(question: str) -> tuple[str, str]:
    """Return (question_line, context_text) from a supplied-context prompt."""
    markers = list(_QUESTION_MARKER.finditer(question))
    if not markers:
        return question.strip(), question
    marker = markers[-1]
    qline = question[marker.end():].strip()
    context_text = question[: marker.start()]
    return qline, context_text


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z0-9]+", (text or "").lower())


def _subsequence(short: list[str], long: list[str]) -> bool:
    it = iter(long)
    return all(tok in it for tok in short)


def _identity_question(qline: str) -> bool:
    """True for ``Who/What was/is <Proper Noun>?`` identity questions."""
    match = re.match(r"^(?:who|what)\s+(?:was|is)\s+", qline, re.IGNORECASE)
    if not match:
        return False
    rest = qline[match.end():]
    return bool(rest and rest[0].isupper())


def _entry_names(context_text: str) -> list[tuple[str, str]]:
    """Return (heading, opening_name) for biographical context entries.

    Only entries whose body opens with a capitalized name followed by a
    parenthetical date/note are considered, so ordinary titles are ignored.
    """
    out: list[tuple[str, str]] = []
    for raw_line in (context_text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        heading_match = re.match(r"^([^:]{1,120}?):\s*(.*)$", line)
        if not heading_match:
            continue
        heading = heading_match.group(1).strip()
        body = heading_match.group(2).strip()
        body_match = re.match(r"^([A-Z][^()]{1,160}?)\s+\(", body)
        if not body_match:
            continue
        opening_name = body_match.group(1).strip()
        if len(_tokens(heading)) >= 2 and len(_tokens(opening_name)) >= 2:
            out.append((heading, opening_name))
    return out


def _name_variants(draft: str, context_text: str) -> list[tuple[str, str]]:
    """Return (heading, opening_name) pairs that are a name variant of draft."""
    draft_tokens = _tokens(draft)
    if len(draft_tokens) < 2:
        return []
    variants: list[tuple[str, str]] = []
    for heading, opening_name in _entry_names(context_text):
        heading_tokens = _tokens(heading)
        opening_tokens = _tokens(opening_name)
        if draft_tokens == heading_tokens and heading_tokens != opening_tokens:
            if _subsequence(heading_tokens, opening_tokens):
                variants.append((heading, opening_name))
        elif draft_tokens == opening_tokens and heading_tokens != opening_tokens:
            if _subsequence(heading_tokens, opening_tokens):
                variants.append((heading, opening_name))
    return variants


def _comma_extended_proper_noun(draft: str, context_text: str) -> str | None:
    """Return a longer proper-noun phrase when draft is a comma-truncated prefix.

    This only fires for an all-capitalized proper-noun draft immediately
    followed in the context by a comma and another capitalized word, e.g.
    ``Portland, Oregon``. It never invents the extension; the returned string
    is the exact context continuation.
    """
    if not _PROPER_NOUN_PHRASE.fullmatch(draft):
        return None
    for match in re.finditer(re.escape(draft), context_text):
        tail = context_text[match.end():]
        extension = _COMMA_EXTENSION.match(tail)
        if extension:
            return draft + extension.group(0)
    return None


def _find_reasons(qline: str, draft: str, context_text: str) -> list[str]:
    reasons: list[str] = []

    if (
        _SINGULAR_WHO.match(qline)
        and not _PLURAL_WHO.match(qline)
        and re.search(r"\s+and\s+", draft)
    ):
        reasons.append("singular_list")

    if _CATEGORY_QUESTION.search(qline):
        reasons.append("category")

    if _AWARD_QUESTION.search(qline):
        reasons.append("award")

    if _ALTERNATIVE_QUESTION.search(qline):
        reasons.append("alternative")

    if _identity_question(qline):
        reasons.append("identity")

    if _OTHER_QUESTION.search(qline):
        reasons.append("other")

    if _LABEL_QUESTION.search(qline):
        reasons.append("label")

    if _PERSON_QUESTION.search(qline) and _name_variants(draft, context_text):
        reasons.append("person_name")

    if not _PERSON_QUESTION.search(qline):
        extended = _comma_extended_proper_noun(draft, context_text)
        if extended:
            reasons.append("comma_place")

    if draft not in context_text:
        reasons.append("not_substring")

    return reasons


def _build_feedback(
    reasons: list[str], qline: str, draft: str, context_text: str
) -> str:
    checks: list[str] = []

    if "singular_list" in reasons:
        checks.append(
            "- The question asks for one entity or value, but your draft joins "
            "several answers with 'and'. Keep only the single entity/value the "
            "question asks for and copy it exactly from the evidence."
        )

    if "category" in reasons:
        checks.append(
            "- The question asks for a category/kind/type/style/genre. Return "
            "the shortest exact evidence label that names it. Do not repeat the "
            "head noun or unit already named in the question, and keep a "
            "compound label only when the modifier alone would be incomplete."
        )

    if "award" in reasons:
        checks.append(
            "- The question asks for an award. Copy the award title exactly as "
            "the evidence gives it, without an organization prefix or a plural "
            "suffix that is not part of the title."
        )

    if "alternative" in reasons:
        checks.append(
            "- The question offers alternatives with 'or'. Resolve the subject "
            "or reference to the passage that states the fact and return the "
            "term used in that passage."
        )

    if "identity" in reasons:
        checks.append(
            "- The question asks who/what the named subject was. Return the "
            "descriptive role, occupation, or category label given in the "
            "evidence, not the subject's birth or legal name."
        )

    if "other" in reasons:
        checks.append(
            "- The question asks for one 'other' item among several named in "
            "the evidence. Return the shortest exact shared name used for that "
            "item; do not expand it to a longer official or institutional form."
        )

    if "label" in reasons:
        checks.append(
            "- The question asks for a sport, role, activity, field, industry, "
            "position, or title. Return the exact label used in the evidence, "
            "not a general term, derived term, or partial phrase."
        )

    if "person_name" in reasons:
        variants = _name_variants(draft, context_text)
        for heading, opening_name in variants[:2]:
            checks.append(
                f"- The evidence gives both a shorter heading ({heading}) and a "
                f"fuller opening name ({opening_name}) for this person. Identify "
                "the passage that directly states the queried fact and copy the "
                "exact name form used there."
            )

    if "comma_place" in reasons:
        extended = _comma_extended_proper_noun(draft, context_text)
        if extended:
            checks.append(
                f"- Your draft looks like a shortened place name; the evidence "
                f"continues with '{extended}'. If the question asks for the "
                "place, copy the complete place phrase exactly."
            )

    if "not_substring" in reasons:
        checks.append(
            "- Your draft is not a verbatim contiguous substring of the supplied "
            "context. Re-read the evidence and copy the exact span that answers "
            "the question. If no passage answers it, return only 'not stated'."
        )

    checks.append(
        "- The final message must contain only the corrected short answer: no "
        "preamble, explanation, hedging, or extra punctuation. Preserve the "
        "evidence's exact wording, capitalization, punctuation, and number form."
    )
    checks.append(
        "If the draft already satisfies every point above, output only the "
        "draft unchanged."
    )

    lines = [
        f"Your draft answer was: {draft}",
        "Before it is scored, re-read the original task and the supplied "
        "context, then check the draft against every point below.",
        *checks,
        "Corrected short answer:",
    ]
    return "\n".join(lines)


async def before_final(answer: str, ctx) -> dict | None:
    question = ctx.question or ""
    if not _is_supplied_context_qa(question):
        return None

    draft = (answer or "").strip()
    if not draft or _CLOSED_FORM.match(draft):
        return None

    state = ctx.state.setdefault("final_verify", {})
    if state.get("done"):
        return None

    qline, context_text = _split_question(question)
    reasons = _find_reasons(qline, draft, context_text)
    if not reasons:
        return None

    state["done"] = True
    return {
        "action": "continue",
        "feedback": _build_feedback(reasons, qline, draft, context_text),
    }
